import itertools

def solve_small(n):
    M = n * (n - 1) // 2
    min_cost = float('inf')

    # We want to assign each match (i,j) a unique day k in {1, ..., M}
    # to minimize sum_{i=1}^n (max_{j \ne i} k(i,j) - min_{j \ne i} k(i,j) + 1)

    # For n=3, M=3
    # There are 3! = 6 permutations of days for the 3 matches.
    matches = list(itertools.combinations(range(n), 2))
    for p in itertools.permutations(range(1, M + 1)):
        cost = 0
        for i in range(n):
            days = []
            for idx, (u, v) in enumerate(matches):
                if i == u or i == v:
                    days.append(p[idx])
            cost += max(days) - min(days) + 1
        if cost < min_cost:
            min_cost = cost
    return min_cost

for n in range(2, 6):
    print(f"n={n}, min_cost={solve_small(n)}")

