def max_sum(M_minus_1):
    # Maximize sum e_1 + ... + e_{M-1}
    # with e_1=0, e_{M-1}=0, e_k+e_{k+1} <= 2, e_k in {0,1,2}
    # This can be solved with DP.
    dp = [[-1] * 3 for _ in range(M_minus_1 + 1)]
    dp[1][0] = 0
    for k in range(1, M_minus_1):
        for e_k in range(3):
            if dp[k][e_k] == -1: continue
            for e_next in range(3):
                if e_k + e_next <= 2:
                    dp[k+1][e_next] = max(dp[k+1][e_next], dp[k][e_k] + e_next)
    return max(dp[M_minus_1][0], dp[M_minus_1][1], dp[M_minus_1][2]) # but e_{M-1}=0

