def solve_small_n(n):
    edges = list(itertools.combinations(range(n), 2))
    m = len(edges)
    min_cost = float('inf')

    for perm in itertools.permutations(edges):
        S = [[] for _ in range(n)]
        for idx, (u, v) in enumerate(perm):
            S[u].append(idx + 1)
            S[v].append(idx + 1)

        cost = 0
        for i in range(n):
            cost += max(S[i]) - min(S[i]) + 1

        if cost < min_cost:
            min_cost = cost

    return min_cost

